def log_containment_ticket(title: str, description: str, priority: str = "medium") -> Dict[str, Any]:
    """
    Creates a security tracking ticket documenting completed containment actions.

    Args:
        title (str): Ticket title.
        description (str): Ticket description/body.
        priority (str): Priority level (e.g. "low", "medium", "high", "critical").

    Returns:
        Dict[str, Any]: {"success": True, "message": ..., "data": {"ticket_id": ..., "priority": ...}}
    """
    try:
        if not title or not str(title).strip():
            raise ValueError("title is required")
        ticket_id = f"SEC-{uuid.uuid4().hex[:8].upper()}"
        logger.info(
            "containment.log_containment_ticket ticket_id=%s priority=%s title=%s",
            ticket_id, priority, title,
        )
        return {
            "success": True,
            "message": f"Ticket {ticket_id} created: {title}",
            "data": {
                "ticket_id": ticket_id,
                "title": title,
                "description": description,
                "priority": priority,
            },
        }
    except Exception as e:
        logger.error("containment.log_containment_ticket failed title=%s error=%s", title, e)
        return {"success": False, "message": f"Failed to create ticket: {e}", "data": None}


